/* One attribute of a move or ability: class id, its AbAttr extraCondition closure
 * (PR_NO_FN if none), and a pointer to its pr_attr_<Class> params. */
typedef struct { uint16_t cls; pr_fn_id cond; const void *p; } pr_attr;

/* pr_attr_isa[cls] = bitmap over classes: cls is (or derives from) that class. */
#define PR_AC_WORDS 14
extern const uint32_t pr_attr_isa[PR_AC_COUNT_][PR_AC_WORDS];
static inline bool pr_attr_is(uint16_t cls, uint16_t base)
{ return (pr_attr_isa[cls][base >> 5] >> (base & 31)) & 1u; }

